#!/usr/bin/env node
/**
 * Convert an ESLint JSON report into GitHub Actions annotations
 * (`::error file=...,line=...,col=...::message`) so failures appear
 * inline in the PR diff and the workflow summary.
 *
 * Usage: node scripts/eslint-annotate.mjs <path-to-eslint-report.json>
 */
import { readFileSync } from "node:fs";
import { relative, resolve } from "node:path";

const reportPath = process.argv[2];
if (!reportPath) {
  console.error("Usage: eslint-annotate.mjs <report.json>");
  process.exit(2);
}

let report;
try {
  report = JSON.parse(readFileSync(reportPath, "utf8"));
} catch (err) {
  console.error(`Could not read ESLint report at ${reportPath}: ${err.message}`);
  process.exit(0); // don't mask the original ESLint exit code
}

const cwd = process.cwd();
let totalErrors = 0;
let totalWarnings = 0;

const escape = (s) =>
  String(s).replace(/%/g, "%25").replace(/\r/g, "%0D").replace(/\n/g, "%0A");

for (const file of report) {
  const path = relative(cwd, resolve(file.filePath));
  for (const m of file.messages ?? []) {
    const level = m.severity === 2 ? "error" : "warning";
    if (level === "error") totalErrors++;
    else totalWarnings++;
    const line = m.line ?? 1;
    const col = m.column ?? 1;
    const rule = m.ruleId ? ` (${m.ruleId})` : "";
    const title = `ESLint${rule}`;
    process.stdout.write(
      `::${level} file=${escape(path)},line=${line},col=${col},title=${escape(title)}::${escape(m.message)}\n`,
    );
  }
}

process.stdout.write(
  `ESLint annotations: ${totalErrors} error(s), ${totalWarnings} warning(s)\n`,
);

/**
 * Validate Tailwind v4 + PostCSS configuration before running Vite.
 *
 * This compiles src/styles.css through the Tailwind v4 compiler so that any
 * CSS / Tailwind syntax error (missing braces, bad @theme blocks, malformed
 * @import, etc.) fails the CI step with a clear message instead of surfacing
 * later inside an opaque Vite build error.
 */
import { readFile } from "node:fs/promises";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { compile } from "@tailwindcss/node";

const projectRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const entry = resolve(projectRoot, "src/styles.css");

async function main() {
  const css = await readFile(entry, "utf8");

  // @tailwindcss/node resolves npm imports (e.g. `@import "tailwindcss"`)
  // and runs the same pipeline as the Vite plugin, so any CSS / Tailwind
  // syntax error surfaces here with a precise message.
  const compiler = await compile(css, {
    base: dirname(entry),
    onDependency: () => {},
  });

  compiler.build([]);

  console.log(`✓ Tailwind/PostCSS config OK (${entry})`);
}

main().catch((err) => {
  console.error("✗ Tailwind/PostCSS validation failed:");
  console.error(err?.stack ?? err);
  process.exit(1);
});

import { cn } from "@/lib/utils";

type Status = "nominal" | "warning" | "critical" | "offline" | "info";

const styles: Record<Status, string> = {
  nominal: "bg-success/15 text-success border-success/40",
  warning: "bg-accent/15 text-accent border-accent/40",
  critical: "bg-destructive/15 text-destructive border-destructive/40",
  offline: "bg-muted text-muted-foreground border-border",
  info: "bg-primary/15 text-primary border-primary/40",
};

export function StatusChip({
  status,
  label,
  pulse,
  className,
}: {
  status: Status;
  label: string;
  pulse?: boolean;
  className?: string;
}) {
  return (
    <span
      className={cn(
        "inline-flex items-center gap-1.5 rounded-full border px-2 py-0.5 text-[10px] font-mono uppercase tracking-wider",
        styles[status],
        className,
      )}
    >
      <span className={cn("h-1.5 w-1.5 rounded-full bg-current", pulse && "live-dot")} />
      {label}
    </span>
  );
}

export function MetricCard({
  label,
  value,
  hint,
  accent,
}: {
  label: string;
  value: string;
  hint?: string;
  accent?: "primary" | "accent" | "success" | "destructive";
}) {
  const ring =
    accent === "destructive"
      ? "ring-destructive/40"
      : accent === "accent"
        ? "ring-accent/40"
        : accent === "success"
          ? "ring-success/40"
          : "ring-primary/30";
  const text =
    accent === "destructive"
      ? "text-destructive"
      : accent === "accent"
        ? "text-accent"
        : accent === "success"
          ? "text-success"
          : "text-primary";
  return (
    <div className={cn("panel relative overflow-hidden p-4 ring-1", ring)}>
      <div className="text-[10px] font-mono uppercase tracking-[0.18em] text-muted-foreground">
        {label}
      </div>
      <div className={cn("mt-2 font-mono text-3xl font-semibold tabular-nums glow-text", text)}>
        {value}
      </div>
      {hint && <div className="mt-1 text-xs text-muted-foreground">{hint}</div>}
      <div className="pointer-events-none absolute -right-8 -top-8 h-24 w-24 rounded-full bg-current opacity-[0.04]" />
    </div>
  );
}

export function PageHeader({
  eyebrow,
  title,
  description,
  actions,
}: {
  eyebrow: string;
  title: string;
  description?: string;
  actions?: React.ReactNode;
}) {
  return (
    <header className="mb-6 flex flex-wrap items-end justify-between gap-4 border-b border-border pb-4">
      <div>
        <div className="text-[11px] font-mono uppercase tracking-[0.22em] text-primary">
          {eyebrow}
        </div>
        <h1 className="mt-1 text-2xl font-semibold tracking-tight text-foreground">{title}</h1>
        {description && (
          <p className="mt-1 max-w-2xl text-sm text-muted-foreground">{description}</p>
        )}
      </div>
      {actions && <div className="flex items-center gap-2">{actions}</div>}
    </header>
  );
}

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const badgeVariants = cva(
  "inline-flex items-center rounded-md border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
  {
    variants: {
      variant: {
        default: "border-transparent bg-primary text-primary-foreground shadow hover:bg-primary/80",
        secondary:
          "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
        destructive:
          "border-transparent bg-destructive text-destructive-foreground shadow hover:bg-destructive/80",
        outline: "text-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return <div className={cn(badgeVariants({ variant }), className)} {...props} />;
}

export { Badge, badgeVariants };

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground shadow hover:bg-primary/90",
        destructive: "bg-destructive text-destructive-foreground shadow-sm hover:bg-destructive/90",
        outline:
          "border border-input bg-background shadow-sm hover:bg-accent hover:text-accent-foreground",
        secondary: "bg-secondary text-secondary-foreground shadow-sm hover:bg-secondary/80",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2",
        sm: "h-8 rounded-md px-3 text-xs",
        lg: "h-10 rounded-md px-8",
        icon: "h-9 w-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : "button";
    return (
